tool_calls:
cd /home/eval/pkgs; mkdir -p bin build; cat > bin/order <<'EOF'
#!/bin/bash
# Usage: order FILE  -- print deterministic topological build order
export LC_ALL=C
[ $# -eq 1 ] && [ -r "$1" ] || { echo "usage: order FILE" >&2; exit 2; }
awk '
{
  sub(/#.*/, ""); gsub(/\r/, "")
  if ($0 ~ /^[ \t]*$/) next
  i = index($0, ":")
  if (i == 0) { name = $0; rest = "" } else { name = substr($0, 1, i-1); rest = substr($0, i+1) }
  gsub(/^[ \t]+|[ \t]+$/, "", name)
  if (name == "") next
  pk[name] = 1
  n = split(rest, d, /[ \t]+/)
  for (j = 1; j <= n; j++) {
    if (d[j] == "") continue
    pk[d[j]] = 1
    if (!((name, d[j]) in edge)) { edge[name, d[j]] = 1; indeg[name]++; rdeps[d[j]] = rdeps[d[j]] " " name }
  }
}
END {
  for (p in pk) if (!indeg[p]) ready[p] = 1
  while (1) {
    best = ""; found = 0
    for (p in ready) if (!found || p < best) { best = p; found = 1 }
    if (!found) break
    delete ready[best]; done[best] = 1; print best
    m = split(rdeps[best], r, " ")
    for (k = 1; k <= m; k++) if (--indeg[r[k]] == 0) ready[r[k]] = 1
  }
  cnt = 0
  for (p in pk) if (!(p in done)) left[++cnt] = p
  if (cnt) {
    for (a = 2; a <= cnt; a++) { v = left[a]; b = a - 1; while (b > 0 && left[b] > v) { left[b+1] = left[b]; b-- } left[b+1] = v }
    s = "cycle: " left[1]; for (a = 2; a <= cnt; a++) s = s " " left[a]
    print s > "/dev/stderr"; exit 1
  }
}' "$1"
EOF
chmod +x bin/order
bin/order deps.txt > build/order.txt; echo rc=$?
bin/order deps-big.txt > build/big-order.txt; echo rc=$?
bin/order deps-cycle.txt > build/cycle-order.txt 2> build/cycle.txt; echo $? > build/cycle.rc
for f in build/*; do echo "== $f"; cat $f; done

